#: What a non-staff user reached before modules existed — kept so nobody
#: loses (or gains) access on deploy.
LEGACY_NON_STAFF_MODULES = ["meetings", "reports", "wiki", "llm_wiki", "drive"]


def grant_legacy_modules(apps, schema_editor):
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))
    UserProfile = apps.get_model("tasks", "UserProfile")
    for user in User.objects.filter(is_staff=False, is_superuser=False):
        profile, _ = UserProfile.objects.get_or_create(user=user)
        profile.modules = LEGACY_NON_STAFF_MODULES
        profile.save(update_fields=["modules"])


